1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	
5	import '../../../entries/domain/entities/entry.dart';
6	import '../../../entries/domain/repositories/entries_repository.dart';
7	import '../../domain/services/audio_transcriber.dart';
8	import '../../domain/services/mic_recorder.dart';
9	
10	/// `AudioEntryCubit`'s own sealed state hierarchy — separate from
11	/// `TextEntryState` (Boundaries: "own sealed `AudioCaptureState`,
12	/// separate from `TextEntryState`"). Unlike `TextEntryState`, no common
13	/// base-class field: the 5 variants don't share a uniform shape the way
14	/// every `TextEntryState` always carries `activeTab`/`text` — [AudioIdle]
15	/// genuinely has nothing in common with [AudioTranscribed], for instance.
16	sealed class AudioCaptureState {
17	  const AudioCaptureState();
18	}
19	
20	/// The state immediately after the modal opens on the Áudio tab exits
21	/// (Never: this story's trivial cross-tab case), and the state a fresh
22	/// `AudioEntryCubit` always starts in.
23	class AudioIdle extends AudioCaptureState {
24	  const AudioIdle();
25	}
26	
27	/// Recording in progress — [elapsedSeconds] backs the running monospace
28	/// timer (Acceptance Criteria) and ticks once per second via
29	/// `AudioEntryCubit`'s own internal `Timer.periodic`.
30	class AudioRecording extends AudioCaptureState {
31	  const AudioRecording({required this.elapsedSeconds});
32	
33	  final int elapsedSeconds;
34	}
35	
36	/// Recording stopped, `AudioTranscriber.transcribe()` in flight —
37	/// `InsertionModal`'s own `_AudioTab` freezes the waveform at 35% opacity
38	/// for the whole duration of this state (Acceptance Criteria).
39	class AudioProcessing extends AudioCaptureState {
40	  const AudioProcessing({required this.path, required this.durationSeconds});
41	
42	  final String path;
43	  final int durationSeconds;
44	}
45	
46	/// Transcription succeeded (even to an empty string) — [text] is editable
47	/// before Salvar (Acceptance Criteria), mirrored into this state by
48	/// `AudioEntryCubit.updateText` the same way `TextEntryCubit.updateText`
49	/// mirrors the Texto field. [saving] is this story's `TextEntrySaving`
50	/// equivalent folded into one state instead of a separate sibling class —
51	/// both [path]/[durationSeconds] (needed for the eventual `create()` call)
52	/// stay fixed across a save attempt, so there's nothing a sibling state
53	/// would add that a boolean field doesn't already cover just as clearly.
54	class AudioTranscribed extends AudioCaptureState {
55	  const AudioTranscribed({
56	    required this.path,
57	    required this.durationSeconds,
58	    required this.text,
59	    required this.saving,
60	  });
61	
62	  final String path;
63	  final int durationSeconds;
64	  final String text;
65	  final bool saving;
66	
67	  AudioTranscribed copyWith({String? text, bool? saving}) => AudioTranscribed(
68	    path: path,
69	    durationSeconds: durationSeconds,
70	    text: text ?? this.text,
71	    saving: saving ?? this.saving,
72	  );
73	}
74	
75	/// A save attempt from [AudioTranscribed] succeeded — `InsertionModal`'s
76	/// listener reacts to this exactly like `TextEntrySaved` (announce, then
77	/// pop). Terminal, same rationale as `TextEntrySaved`'s own doc.
78	class AudioSaved extends AudioCaptureState {
79	  const AudioSaved();
80	}
81	
82	/// The last attempt failed — covers all 3 failure rows of the I/O matrix:
83	/// - Mic permission denied -> [path]/[durationSeconds] both `null` ("No
84	///   file to preserve"); [AudioEntryCubit.retry] re-requests permission.
85	/// - Transcription failed -> [path]/[durationSeconds] carry the preserved
86	///   file; [AudioEntryCubit.retry] re-transcribes it, never re-records.
87	/// - Save failed (incl. offline) -> same preserved [path]/
88	///   [durationSeconds]/[text] semantics as `TextEntryError`; the modal's
89	///   `_AudioTab` keeps showing the editable text with Salvar re-enabled
90	///   rather than routing back through [AudioEntryCubit.retry].
91	class AudioError extends AudioCaptureState {
92	  const AudioError({
93	    required this.path,
94	    required this.durationSeconds,
95	    required this.message,
96	    this.text,
97	  });
98	
99	  final String? path;
100	  final int? durationSeconds;
101	  final String message;
102	
103	  /// Non-null only for a save failure — lets `_AudioTab` keep rendering
104	  /// the editable text field under the inline error, same as
105	  /// `TextEntryError`'s own `_TextoTab` rendering.
106	  final String? text;
107	}
108	
109	/// Drives the Áudio tab's recording -> processing -> transcribed/error
110	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
111	/// tap, same convention as `TextEntryCubit` — [MicRecorder]/
112	/// [AudioTranscriber] themselves stay long-lived `get_it` singletons
113	/// (`capture_injection.dart`), shared across every modal open the way
114	/// `EntriesRepository` already is for `TextEntryCubit`.
115	class AudioEntryCubit extends Cubit<AudioCaptureState> {
116	  AudioEntryCubit(this._micRecorder, this._audioTranscriber, this._repository)
117	    : super(const AudioIdle());
118	
119	  final MicRecorder _micRecorder;
120	  final AudioTranscriber _audioTranscriber;
121	  final EntriesRepository _repository;
122	
123	  Timer? _elapsedTimer;
124	
125	  /// Forwarded straight from [MicRecorder.amplitudeStream] — lets
126	  /// `_AudioTab`'s waveform animate without ever importing `package:record`
127	  /// itself (Boundaries).
128	  Stream<double> get amplitudeStream => _micRecorder.amplitudeStream;
129	
130	  /// Starts recording — called from `InsertionModal`'s tab-switch
131	  /// listener the instant the Áudio tab becomes active (Acceptance
132	  /// Criteria: "recording starts immediately"), and again by [retry] when
133	  /// the last attempt failed before any file ever existed (permission
134	  /// denied). Ignored while a recording is already in progress, so a
135	  /// stray second call (e.g. a rebuild re-triggering the listener) can't
136	  /// start a second, overlapping session.
137	  Future<void> startRecording() async {
138	    if (state is AudioRecording) {
139	      return;
140	    }
141	    final hasPermission = await _micRecorder.hasPermission();
142	    if (isClosed) {
143	      return;
144	    }
145	    if (!hasPermission) {
146	      emit(
147	        const AudioError(
148	          path: null,
149	          durationSeconds: null,
150	          message:
151	              'Permissão de microfone negada. Toque em "Tentar novamente" '
152	              'para permitir o acesso.',
153	        ),
154	      );
155	      return;
156	    }
157	    await _micRecorder.start();
158	    if (isClosed) {
159	      return;
160	    }
161	    _startElapsedTimer();
162	    emit(const AudioRecording(elapsedSeconds: 0));
163	  }
164	
165	  void _startElapsedTimer() {
166	    _elapsedTimer?.cancel();
167	    var elapsed = 0;
168	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
169	      elapsed++;
170	      if (state is AudioRecording) {
171	        emit(AudioRecording(elapsedSeconds: elapsed));
172	      }
173	    });
174	  }
175	
176	  /// Stops recording and immediately kicks off transcription — the I/O
177	  /// matrix's "Happy path"/"Transcription fails" rows. Ignored outside
178	  /// [AudioRecording] (e.g. a stray second tap on the stop control).
179	  Future<void> stopRecording() async {
180	    if (state is! AudioRecording) {
181	      return;
182	    }
183	    _elapsedTimer?.cancel();
184	    final recording = await _micRecorder.stop();
185	    if (isClosed) {
186	      return;
187	    }
188	    if (recording == null) {
189	      // Stopped with nothing actually captured — the I/O matrix has no
190	      // dedicated row for this (it should be unreachable in practice: the
191	      // recorder was just started above), but `AudioError` with no file
192	      // still gives the user a path back in via retry's permission-
193	      // re-request branch rather than leaving the cubit stuck mid-flow.
194	      emit(
195	        const AudioError(
196	          path: null,
197	          durationSeconds: null,
198	          message: 'Não foi possível gravar o áudio.',
199	        ),
200	      );
201	      return;
202	    }
203	    emit(
204	      AudioProcessing(
205	        path: recording.path,
206	        durationSeconds: recording.durationSeconds,
207	      ),
208	    );
209	    await _transcribe(recording.path, recording.durationSeconds);
210	  }
211	
212	  Future<void> _transcribe(String path, int durationSeconds) async {
213	    final text = await _audioTranscriber.transcribe(path);
214	    if (isClosed) {
215	      return;
216	    }
217	    // Guards a tab switch away mid-processing (`cancel()`, below) that
218	    // already reset the state to `AudioIdle` by the time this resolves —
219	    // without this, the eventual transcription result would still land
220	    // and resurrect a flow the user already left.
221	    if (state is! AudioProcessing ||
222	        (state as AudioProcessing).path != path) {
223	      return;
224	    }
225	    if (text == null) {
226	      emit(
227	        AudioError(
228	          path: path,
229	          durationSeconds: durationSeconds,
230	          message: 'Não foi possível transcrever o áudio.',
231	        ),
232	      );
233	      return;
234	    }
235	    emit(
236	      AudioTranscribed(
237	        path: path,
238	        durationSeconds: durationSeconds,
239	        text: text,
240	        saving: false,
241	      ),
242	    );
243	  }
244	
245	  /// "Tentar novamente" — re-requests permission when no file was ever
246	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
247	  /// matrix: never re-records, never auto-retries on its own). A no-op
248	  /// outside [AudioError], or for a save failure (non-null [AudioError.
249	  /// text]) — that case's own retry is just tapping Salvar again, handled
250	  /// by [save] directly, not this method.
251	  Future<void> retry() async {
252	    final current = state;
253	    if (current is! AudioError || current.text != null) {
254	      return;
255	    }
256	    final path = current.path;
257	    final durationSeconds = current.durationSeconds;
258	    if (path == null || durationSeconds == null) {
259	      await startRecording();
260	      return;
261	    }
262	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
263	    await _transcribe(path, durationSeconds);
264	  }
265	
266	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
267	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
268	  /// save is already in flight, same rationale as `TextEntryCubit.
269	  /// updateText`.
270	  void updateText(String text) {
271	    final current = state;
272	    if (current is AudioTranscribed && !current.saving) {
273	      emit(current.copyWith(text: text));
274	    }
275	  }
276	
277	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
278	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
279	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
280	  /// ever fires. A no-op for every other state — in particular
281	  /// [AudioTranscribed]/[AudioError], where the Never clause's trivial
282	  /// scope (resource safety only, not full Story 3.4 cancel-safety) means
283	  /// leaving the tab must preserve the result rather than discard it.
284	  Future<void> cancel() async {
285	    final current = state;
286	    if (current is AudioRecording) {
287	      _elapsedTimer?.cancel();
288	      await _micRecorder.cancel();
289	      if (isClosed) {
290	        return;
291	      }
292	      emit(const AudioIdle());
293	    } else if (current is AudioProcessing) {
294	      // The recorder itself is already stopped by the time this state is
295	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
296	      // — only resetting the cubit's own state is left, so the pending
297	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
298	      // (above) drops its result instead of resurrecting this flow.
299	      emit(const AudioIdle());
300	    }
301	  }
302	
303	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
304	  /// with `source: audio` and `mediaDurationSeconds` for the current
305	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
306	  /// no-double-submit guards exactly (Boundaries).
307	  Future<void> save() async {
308	    final current = state;
309	    if (current is! AudioTranscribed || current.saving) {
310	      return;
311	    }
312	    final text = current.text.trim();
313	    if (text.isEmpty) {
314	      return;
315	    }
316	    emit(current.copyWith(saving: true));
317	    final result = await _repository.create(
318	      content: text,
319	      source: EntrySource.audio,
320	      mediaDurationSeconds: current.durationSeconds,
321	    );
322	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
323	    // cubit's `close()` can race the awaited call above (e.g. the modal's
324	    // barrier is dismissed mid-save).
325	    if (isClosed) {
326	      return;
327	    }
328	    result.match(
329	      (failure) => emit(
330	        AudioError(
331	          path: current.path,
332	          durationSeconds: current.durationSeconds,
333	          message: failure.message,
334	          text: text,
335	        ),
336	      ),
337	      (_) => emit(const AudioSaved()),
338	    );
339	  }
340	
341	  @override
342	  Future<void> close() {
343	    _elapsedTimer?.cancel();
344	    return super.close();
345	  }
346	}
